script:
(function () {
  'use strict';
  // 365/360 loan: the same fixed monthly payment, three ways of charging interest.
  //   Payment M = L x i / (1 - (1 + i)^-n), i = rate / 12, n = amortization years x 12 (L / n at 0%).
  //   Interest for a period = balance x rate x day fraction:
  //     Actual/360 ("365/360"): actual days / 360
  //     Actual/365: actual days / 365 (366-day years are not treated differently)
  //     30/360: each regular month counts 30 days; the first period from funding to the first
  //       payment uses the 30/360 US day count (day 31 -> 30) / 360.
  //   Payment k is due on the first payment date + (k - 1) months (day clamped to the month's end).
  //   The last payment of the loan term (or an earlier one that clears the debt) pays the
  //   remaining balance plus its interest.
  // Dates are whole day numbers parsed from YYYY-MM-DD (H. Hinnant's days_from_civil), so time
  // zones and daylight saving can't shift a day.
  // Verified (Node, scratchpad tests/g1031_d36.test.js) against independent calculations:
  //   one month of interest on $100,000 at 6% over 31 days: Actual/360 $516.67, Actual/365 $509.59,
  //   30/360 $500.00; 30/360 with a one-month first period reproduces the standard amortization
  //   exactly ($200,000, 6%, 30 years: $1,199.10 a month, final payment within a cent, total
  //   interest $231,676.38 closed form); $500,000 at 7% / 25-year amortization: $3,533.90 a month;
  //   a Python day-by-day replica of the Actual/360 schedule matches the total interest and final
  //   payment to the cent; Actual/360 effective rate = 7% x 365/360 = 7.0972%.
  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var NAMES = { a360: 'Actual/360 (365/360)', a365: 'Actual/365', t360: '30/360' };
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var last = null, firstTouched = false;

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function daysFromCivil(y, m, d) {
    y -= m <= 2 ? 1 : 0;
    var era = Math.floor(y / 400), yoe = y - era * 400;
    var doy = Math.floor((153 * ((m + 9) % 12) + 2) / 5) + d - 1;
    var doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
    return era * 146097 + doe - 719468;
  }
  function civilFromDays(z) {
    z += 719468;
    var era = Math.floor(z / 146097), doe = z - era * 146097;
    var yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
    var doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
    var mp = Math.floor((5 * doy + 2) / 153);
    var d = doy - Math.floor((153 * mp + 2) / 5) + 1, m = mp < 10 ? mp + 3 : mp - 9;
    return { y: yoe + era * 400 + (m <= 2 ? 1 : 0), m: m, d: d };
  }
  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || '').trim());
    if (!m) return NaN;
    var y = +m[1], mo = +m[2], d = +m[3];
    if (mo < 1 || mo > 12 || d < 1 || d > 31) return NaN;
    var z = daysFromCivil(y, mo, d), c = civilFromDays(z);
    return c.y === y && c.m === mo && c.d === d ? z : NaN;
  }
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  function iso(z) { var c = civilFromDays(z); return c.y + '-' + pad(c.m) + '-' + pad(c.d); }
  function fmt(z) { var c = civilFromDays(z); return MONTHS[c.m - 1] + ' ' + c.d + ', ' + c.y; }
  function daysInMonth(y, m) { return daysFromCivil(m === 12 ? y + 1 : y, m === 12 ? 1 : m + 1, 1) - daysFromCivil(y, m, 1); }
  function addMonths(z, k) {
    var c = civilFromDays(z), t = (c.m - 1) + k, y = c.y + Math.floor(t / 12), m = ((t % 12) + 12) % 12 + 1;
    return daysFromCivil(y, m, Math.min(c.d, daysInMonth(y, m)));
  }
  function days360(a, b) {
    var x = civilFromDays(a), y = civilFromDays(b), d1 = x.d, d2 = y.d;
    if (d1 === 31) d1 = 30;
    if (d2 === 31 && d1 >= 30) d2 = 30;
    return 360 * (y.y - x.y) + 30 * (y.m - x.m) + (d2 - d1);
  }

  function payment(loan, rate, n) {
    var i = rate / 12;
    if (i === 0) return loan / n;
    return loan * i / (1 - Math.pow(1 + i, -n));
  }

  function schedule(loan, rate, amortN, termN, start, first, method) {
    var pay = payment(loan, rate, amortN), bal = loan, prev = start, rows = [], total = 0;
    for (var k = 1; k <= termN; k++) {
      var date = addMonths(first, k - 1), days, frac;
      if (method === 't360') { days = k === 1 ? days360(prev, date) : 30; frac = days / 360; }
      else { days = date - prev; frac = days / (method === 'a360' ? 360 : 365); }
      var interest = bal * rate * frac;
      var amount = pay;
      if (k === termN || bal + interest <= pay + 0.005) amount = bal + interest;
      var principal = amount - interest;
      bal -= principal;
      if (Math.abs(bal) < 0.005) bal = 0;
      total += interest;
      rows.push({ n: k, date: date, days: days, payment: amount, interest: interest, principal: principal, balance: bal });
      prev = date;
      if (bal === 0) break;
    }
    var lastRow = rows[rows.length - 1];
    return { payment: pay, rows: rows, interest: total, finalPayment: lastRow.payment, lastDate: lastRow.date, totalPaid: loan + total };
  }

  function renderSchedule() {
    var head = el('d36Head'), body = el('d36Schedule');
    if (!last) { body.innerHTML = ''; head.innerHTML = ''; return; }
    var s = last[el('d36Method').value] || last.a360, html = [];
    if (el('d36View').value === 'year') {
      head.innerHTML = '<tr><th scope="col">Year</th><th scope="col">Payments</th><th scope="col">Interest</th><th scope="col">Principal</th><th scope="col">Ending balance</th></tr>';
      var acc = null;
      s.rows.forEach(function (r, idx) {
        var y = civilFromDays(r.date).y;
        if (!acc || acc.y !== y) { if (acc) html.push(acc); acc = { y: y, p: 0, i: 0, pr: 0, b: 0 }; }
        acc.p += r.payment; acc.i += r.interest; acc.pr += r.principal; acc.b = r.balance;
        if (idx === s.rows.length - 1) html.push(acc);
      });
      html = html.map(function (a) {
        return '<tr><td>' + a.y + '</td><td>' + money.format(a.p) + '</td><td>' + money.format(a.i) + '</td><td>' + money.format(a.pr) +
          '</td><td>' + money.format(a.b) + '</td></tr>';
      });
    } else {
      head.innerHTML = '<tr><th scope="col">#</th><th scope="col">Date</th><th scope="col">Days</th><th scope="col">Payment</th><th scope="col">Interest</th><th scope="col">Principal</th><th scope="col">Balance</th></tr>';
      s.rows.forEach(function (r) {
        html.push('<tr><td>' + r.n + '</td><td>' + fmt(r.date) + '</td><td>' + r.days + '</td><td>' + money.format(r.payment) + '</td><td>' +
          money.format(r.interest) + '</td><td>' + money.format(r.principal) + '</td><td>' + money.format(r.balance) + '</td></tr>');
      });
    }
    body.innerHTML = html.join('');
  }

  function clear() {
    ['d36Payment', 'd36Extra', 'd36EffRate', 'd36LastDate', 'd36Summary'].forEach(function (id) { setText(id, '–'); });
    el('d36Compare').innerHTML = '';
    last = null;
    renderSchedule();
  }

  function update(e) {
    var target = e && e.target ? e.target.id : '';
    if (target === 'd36First') firstTouched = true;
    var start = parseDate(el('d36Start').value);
    if (target === 'd36Start' && !firstTouched && !isNaN(start)) el('d36First').value = iso(addMonths(start, 1));
    var first = parseDate(el('d36First').value);
    var loan = read('d36Loan'), rate = read('d36Rate'), amort = read('d36Amort'), term = read('d36Term');
    var err = el('d36Error'), msg = '';
    if ([loan, rate, amort, term].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (loan <= 0 || loan > 1e10) msg = 'Enter a loan amount above $0.';
    else if (rate < 0 || rate > 50) msg = 'Enter an interest rate from 0% to 50%.';
    else if (amort < 1 || amort > 40 || Math.round(amort * 12) !== amort * 12) msg = 'Enter an amortization term of 1 to 40 years.';
    else if (term < 1 || term > 40 || Math.round(term * 12) !== term * 12) msg = 'Enter a loan term of 1 to 40 years.';
    else if (term > amort) msg = 'The loan term can\'t be longer than the amortization term.';
    else if (isNaN(start) || isNaN(first)) msg = 'Enter the funding date and the first payment date.';
    else if (first <= start) msg = 'The first payment date must be after the funding date.';
    else if (first - start > 366) msg = 'The first payment must be within a year of the funding date.';
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { clear(); return; }

    var r = rate / 100, an = Math.round(amort * 12), tn = Math.round(term * 12);
    last = {
      a360: schedule(loan, r, an, tn, start, first, 'a360'),
      a365: schedule(loan, r, an, tn, start, first, 'a365'),
      t360: schedule(loan, r, an, tn, start, first, 't360')
    };
    var base = last.t360.interest;
    setText('d36Payment', money.format(last.a360.payment));
    setText('d36Extra', money.format(last.a360.interest - base));
    setText('d36EffRate', (Math.round(rate * 365 / 360 * 10000) / 10000) + '%');
    setText('d36LastDate', fmt(last.a360.lastDate));
    setText('d36Summary', 'Charging ' + rate + '% on an actual/360 basis costs ' + money.format(last.a360.interest - base) +
      ' more interest than 30/360 and ' + money.format(last.a360.interest - last.a365.interest) + ' more than actual/365 over ' +
      last.a360.rows.length + ' payments. Because the payment stays the same, the difference is collected in the final payment.');
    el('d36Compare').innerHTML = ['a360', 'a365', 't360'].map(function (k) {
      var d = last[k].interest - base;
      return '<tr><td>' + NAMES[k] + '</td><td>' + money.format(last[k].interest) + '</td><td>' + money.format(last[k].finalPayment) +
        '</td><td>' + (Math.abs(d) < 0.005 ? '–' : (d > 0 ? '+' : '−') + money.format(Math.abs(d))) + '</td></tr>';
    }).join('');
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var startEl = el('d36Start'), firstEl = el('d36First');
    if (!startEl.value) {
      var t = new Date(), today = daysFromCivil(t.getFullYear(), t.getMonth() + 1, t.getDate());
      startEl.value = iso(today);
    }
    if (!firstEl.value) { var s = parseDate(startEl.value); if (!isNaN(s)) firstEl.value = iso(addMonths(s, 1)); }
    var form = el('d36Form');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('d36Method').addEventListener('change', renderSchedule);
    el('d36View').addEventListener('change', renderSchedule);
    update();
  });
})();
